        decoded = unquote(decoded)

    if self._allow_harmful_protocols and decoded.startswith(tuple(self._allow_harmful_protocols)):
        return escape_text(url)

    if decoded.startswith(self.HARMFUL_PROTOCOLS) and not decoded.startswith(self.GOOD_DATA_PROTOCOLS):
